// n8n gọi luồng này khi một lần chạy của luồng chính dừng vì lỗi (khối nào đó ném lỗi, không có "tiếp tục khi lỗi").
// Gom thông tin cần thiết để báo WordPress đánh dấu các lượt còn mở là "failed".
const e = $input.first().json;
const exec = e.execution ?? {};
const wf = e.workflow ?? {};
const err = exec.error ?? {};

const info = {
  workflow_id: wf.id ?? null,
  workflow_name: wf.name ?? null,
  execution_id: exec.id ?? null,
  execution_url: exec.url ?? null,
  mode: exec.mode ?? null,
  node: exec.lastNodeExecuted ?? err.node?.name ?? null,
  error: [err.message, err.description].filter(Boolean).join(' | ').slice(0, 1500) || 'không có thông báo lỗi',
  retry_of: exec.retryOf ?? null,
};
console.log('[socialsync] Luồng chính lỗi', JSON.stringify(info));

// Chỉ xử lý lỗi của luồng SocialSync chính và lần chạy có mã số (lỗi lúc kích hoạt luồng không có lần chạy).
if (info.workflow_id !== 'SocialSyncMain01' || !info.execution_id) {
  console.log('[socialsync] Bỏ qua: không phải lần chạy của luồng SocialSyncMain01');
  return [];
}
return [{ json: info }];

const r = $input.first().json;
const info = $('Tóm tắt lỗi').first().json;
const ok = r.statusCode === 200 && r.body && r.body.ok === true;
console.log('[socialsync] WordPress trả lời báo lỗi', JSON.stringify({ ok, statusCode: r.statusCode ?? null, body: r.body ?? null, error: r.error?.message ?? null }));
return [{ json: { ...info, wordpress_ok: ok, wordpress_status: r.statusCode ?? null, failed_jobs: r.body?.failed_jobs ?? [], closed: r.body?.closed ?? [] } }];
